mapper.select:
SELECT kb.id, kb.user_id, kb.name, kb.description, kb.status, (SELECT COUNT(*) FROM document d WHERE d.knowledge_base_id = kb.id AND d.deleted = 0) AS document_count, kb.created_at, kb.updated_at, kb.deleted FROM knowledge_base kb WHERE kb.deleted = 0 AND kb.user_id = #{userId}
AND kb.status = #{status}
AND kb.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY kb.id DESC

SELECT FROM knowledge_base kb LEFT JOIN user u ON u.id = kb.user_id WHERE kb.deleted = 0
AND kb.user_id = #{userId}
AND kb.status = #{status}
AND kb.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY kb.id DESC
